import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    adj: list[list[tuple[int, int, int]]] = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        if u == v:
            continue
        zbit = 0 if zone == -1 else 1 << zone
        adj[u].append((v, cost, zbit))
        adj[v].append((u, cost, zbit))

    seen_stations: set[tuple[int, int]] = set()
    station_list: list[tuple[int, int, int]] = []
    for stop, z in stations:
        if (stop, z) not in seen_stations:
            seen_stations.add((stop, z))
            station_list.append((stop, 1 << z, prices[z]))

    num_masks = 1 << len(prices)
    n_bits = (n - 1).bit_length()
    u_mask = (1 << n_bits) - 1
    target = n - 1
    INF = 1 << 60
    ans = INF

    seeds: list[dict[int, int]] = [{} for _ in range(num_masks)]
    seeds[0][0] = 0

    heappush = heapq.heappush
    heappop = heapq.heappop

    for mask in range(num_masks):
        layer_seeds = seeds[mask]
        if not layer_seeds:
            continue

        dist = [ans] * n
        heap: list[int] = []
        for u, d in layer_seeds.items():
            if d < dist[u]:
                dist[u] = d
                heappush(heap, (d << n_bits) | u)

        if not heap:
            continue

        while heap:
            item = heappop(heap)
            d = item >> n_bits
            u = item & u_mask
            if d > dist[u]:
                continue
            if d >= ans:
                break
            if u == target:
                ans = d
                break
            for v, cost, zbit in adj[u]:
                nd = d if (mask & zbit) else d + cost
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd << n_bits) | v)

        if mask == 0 and ans == INF:
            return -1

        for stop, zbit, price in station_list:
            if not (mask & zbit):
                d_stop = dist[stop]
                if d_stop < ans:
                    nd = d_stop + price
                    if nd < ans:
                        nmask = mask | zbit
                        nseeds = seeds[nmask]
                        if nd < nseeds.get(stop, ans):
                            nseeds[stop] = nd

    return -1 if ans == INF else ans
